        "aspectIndex": 7,
        "criterionId": "content",
        "earned": true,
        "quote": "Bonifácio manteve conversas com o cônsul dos EUA no Brasil, Peter Sartoris, para entender a posição do país sobre a independência brasileira e para tentar obter apoio regional."
      }
